function n4MapOverlay(){if(!n4Active())return;const line=$('suggestedRoute'),route=draft?.route||mission.candidateRoute,show=!!(n4Pending()&&route&&(draft||mission.n4Plan));if(line){line.setAttribute('points',show?route.map(p=>p.join(',')).join(' '):'');line.style.display=show?'':'none';line.classList.toggle('event-highlight',show&&Date.now()<(state.n4UpdatedUntil||0));}}
